   1	/**
   2	 * Declarative entity-link resolver at event ingestion.
   3	 *
   4	 * A connector declares `eventKinds[kind].attributions[]` rules. Each attribution
   5	 * maps event identifier fields (phone, email, wa_jid, ...) to a target entity.
   6	 * The ingestion pipeline:
   7	 *   1) Extracts + normalizes identifiers from each event.
   8	 *   2) Looks them up in the normalized `entity_identities` table
   9	 *      (UNIQUE per (org, namespace, identifier)).
  10	 *   3) Links to the matched entity, creates on miss (when autoCreate=true),
  11	 *      logs a merge candidate when one event's identifiers resolve to
  12	 *      multiple distinct entities.
  13	 *   4) Merges declared `traits` onto entities.metadata per merge strategy.
  14	 *
  15	 * Never mutates `events.entity_ids` — events stay immutable, JOIN-at-read
  16	 * recovers the relationship via entity_identities.
  17	 */
  18	
  19	import { randomBytes } from 'node:crypto';
  20	import {
  21	  ACL_RESOURCE_TYPE_SLUG,
  22	  type EntityIdentitySpec,
  23	  type EntityLinkPredicate,
  24	  type EntityTraitSpec,
  25	  type EventAttributionRule,
  26	} from '@lobu/connector-sdk';
  27	import { normalizeIdentifier } from '@lobu/connector-sdk/identity-normalize';
  28	import { ensureResourceEntityType } from '../authz/acl-resource-type';
  29	import { type DbClient, getDb, pgBigintArray, pgTextArray } from '../db/client';
  30	import { normalizeConnectorIdentityValue } from '../identity/connector-identity-modules';
  31	import {
  32	  hardDeleteEntityRows,
  33	  patchEntityRows,
  34	  tryInsertEntityRow,
  35	  withEntityWriteTransaction,
  36	} from './entity-management';
  37	import logger from './logger';
  38	import { getValueAtPath } from './object-path';
  39	import { TtlCache } from './ttl-cache';
  40	
  41	interface BatchItem {
  42	  origin_type?: string;
  43	  metadata?: Record<string, unknown>;
  44	  title?: string | null;
  45	}
  46	
  47	type ResolvedEventAttributionRule = {
  48	  role: EventAttributionRule['role'];
  49	  entityType: string;
  50	  autoCreate?: boolean;
  51	  createWhen?: EntityLinkPredicate;
  52	  titlePath?: string;
  53	  identities: EntityIdentitySpec[];
  54	  traits?: Record<string, EntityTraitSpec>;
  55	};
  56	
  57	interface RuleMap {
  58	  [kind: string]: ResolvedEventAttributionRule[];
  59	}
  60	
  61	type EventKindAttributionDefinition = {
  62	  attributions?: EventAttributionRule[];
  63	};
  64	
  65	function resolveEventAttributions(
  66	  def: EventKindAttributionDefinition | undefined
  67	): ResolvedEventAttributionRule[] {
  68	  return (def?.attributions ?? []).flatMap((rule) => {
  69	    const identities = rule.target.identities;
  70	    if (!rule.target.entityType || !Array.isArray(identities) || identities.length === 0) {
  71	      return [];
  72	    }
  73	    return [
  74	      {
  75	        role: rule.role,
  76	        entityType: rule.target.entityType,
  77	        autoCreate: rule.autoCreate,
  78	        createWhen: rule.target.createWhen,
  79	        titlePath: rule.target.titlePath,
  80	        identities,
  81	        traits: rule.traits,
  82	      },
  83	    ];
  84	  });
  85	}
  86	
  87	const RULES_CACHE_TTL_MS = 60_000;
  88	// Per-pod caches — no cross-replica sharing.
  89	const rulesCache = new TtlCache<RuleMap>(RULES_CACHE_TTL_MS);
  90	const creatorCache = new TtlCache<string | null>(RULES_CACHE_TTL_MS);
  91	
  92	async function resolveOrgCreator(orgId: string): Promise<string | null> {
  93	  return creatorCache.getOrSet(orgId, async () => {
  94	    const sql = getDb();
  95	    const rows = await sql<{ userId: string }>`
  96	      SELECT "userId"
  97	      FROM "member"
  98	      WHERE "organizationId" = ${orgId}
  99	      ORDER BY CASE role WHEN 'owner' THEN 0 WHEN 'admin' THEN 1 ELSE 2 END,
 100	               "createdAt" ASC
 101	      LIMIT 1
 102	    `;
 103	    return rows.length > 0 ? rows[0].userId : null;
 104	  });
 105	}
 106	
 107	function randomSlug(entityType: string): string {
 108	  const prefix =
 109	    entityType
 110	      .replace(/^\$/, '')
 111	      .replace(/[^a-z0-9]+/gi, '-')
 112	      .toLowerCase() || 'entity';
 113	  return `${prefix}-${randomBytes(5).toString('hex')}`;
 114	}
 115	
 116	async function loadEventAttributionRules(params: {
 117	  connectorKey: string;
 118	  feedKey: string;
 119	  orgId: string;
 120	}): Promise<RuleMap> {
 121	  const cacheKey = `${params.orgId}:${params.connectorKey}:${params.feedKey}`;
 122	  return rulesCache.getOrSet(cacheKey, async () => {
 123	    const sql = getDb();
 124	    const rows = await sql`
 125	      SELECT feeds_schema
 126	      FROM connector_definitions
 127	      WHERE key = ${params.connectorKey}
 128	        AND organization_id = ${params.orgId}
 129	      LIMIT 1
 130	    `;
