 191	          }
 192	        }
 193	      }
 194	    }
 195	    return result;
 196	  });
 197	  return map[params.entityType]?.[0] ?? null;
 198	}
 199	
 200	export function clearEntityLinkRulesCache(): void {
 201	  rulesCache.clear();
 202	  creatorCache.clear();
 203	}
