 205	/**
 206	 * A single already-normalized identity ready for lookup/create — the resolved
 207	 * counterpart of the declarative {@link EntityIdentitySpec} (which carries an
 208	 * `eventPath` to extract FROM an event). The store-only sender path hands these
 209	 * in directly, having normalized upstream.
 210	 */
 211	export type ResolvedIdentity = {
 212	  namespace: string;
 213	  identifier: string;
 214	  matchOnly: boolean;
 215	  primary: boolean;
 216	};
 217	
 218	type ExtractedLink = {
 219	  identities: ResolvedIdentity[];
 220	  traits: Map<string, unknown>;
 221	  title: string;
 222	};
 223	
 224	/**
 225	 * Evaluate a rule's `createWhen` gate against the event item. Returns true (mint
 226	 * allowed) when the predicate is absent or every declared condition holds; all
 227	 * conditions AND together. Only gates the CREATE-on-miss branch — matching an
 228	 * existing entity is never affected.
 229	 */
 230	function passesCreateWhen(predicate: EntityLinkPredicate | undefined, item: BatchItem): boolean {
 231	  if (!predicate) return true;
 232	  const value = getValueAtPath(item, predicate.path);
 233	  if (predicate.equals !== undefined && value !== predicate.equals) return false;
 234	  if (predicate.notEquals !== undefined && value === predicate.notEquals) return false;
 235	  if (predicate.exists !== undefined) {
 300	  for (const spec of rule.identities) {
 301	    const raw = getValueAtPath(item, spec.eventPath);
 302	    if (typeof raw !== 'string' || raw.length === 0) continue;
 303	    const normalized = normalizeIdentityValue(spec.namespace, raw);
 304	    if (!normalized) continue;
 305	    identities.push({
 306	      namespace: spec.namespace,
 307	      identifier: normalized,
 308	      matchOnly: spec.matchOnly === true,
 309	      primary: spec.primary === true,
 310	    });
 311	  }
 312	  if (identities.length === 0) return null;
 313	
 314	  const traits = new Map<string, unknown>();
 315	  if (rule.traits) {
 316	    for (const [key, spec] of Object.entries(rule.traits)) {
 317	      const value = getValueAtPath(item, spec.eventPath);
 318	      if (value !== undefined) traits.set(key, value);
 319	    }
 320	  }
 321	
 322	  const rawTitle = rule.titlePath ? getValueAtPath(item, rule.titlePath) : undefined;
 323	  const title = typeof rawTitle === 'string' && rawTitle.trim() ? rawTitle.trim() : '';
 324	
 325	  return { identities, traits, title };
 326	}
 327	
 328	/**
 329	 * Resolve identity keys to their owning entity — TYPE-AGNOSTIC.
 330	 *
 331	 * An identity value belongs to at most ONE entity org-wide (the
 332	 * `idx_entity_identities_live_unique` index on `(org, namespace, identifier)`),
 333	 * so a key resolves to a single entity of ANY type. We deliberately do NOT
 334	 * filter by the rule's target `entityType`: a `slack_user_id` owned by a
 335	 * signed-in `$member` must resolve to that `$member` even when a `person`-typed
 336	 * rule looks it up, so attribution and ACL converge on one entity instead of
 337	 * minting a duplicate `person` (the #1646 cross-source collapse, now automatic).
 338	 * Mirrors `access-graph.resolveMembers`, which is already identity-first +
 339	 * type-agnostic. The target `entityType` still governs CREATE-on-miss.
 340	 */
 341	async function lookupMatches(
 342	  sql: DbClient,
 343	  params: {
 344	    orgId: string;
 345	    identities: ExtractedLink['identities'][];
 346	  }
 347	): Promise<Map<string, number>> {
 348	  const keys = new Set<string>();
 349	  for (const arr of params.identities) {
 350	    for (const id of arr) keys.add(`${id.namespace}\u0000${id.identifier}`);
 351	  }
 352	  if (keys.size === 0) return new Map();
 353	
 354	  const namespaces: string[] = [];
 355	  const identifiers: string[] = [];
 356	  for (const key of keys) {
 357	    const [ns, ident] = key.split('\u0000');
 358	    namespaces.push(ns);
 359	    identifiers.push(ident);
 360	  }
 361	
 362	  const rows = await sql<{ entity_id: number | string; namespace: string; identifier: string }>`
 363	    SELECT ei.entity_id, ei.namespace, ei.identifier
 364	    FROM entity_identities ei
 365	    JOIN entities e ON e.id = ei.entity_id
 366	    WHERE ei.organization_id = ${params.orgId}
 367	      AND ei.deleted_at IS NULL
 368	      AND e.deleted_at IS NULL
 369	      AND (ei.namespace, ei.identifier) IN (
 370	        SELECT ns, ident FROM unnest(${pgTextArray(namespaces)}::text[], ${pgTextArray(identifiers)}::text[]) AS u(ns, ident)
 371	      )
 372	  `;
 373	
 374	  const out = new Map<string, number>();
 375	  for (const row of rows) {
 376	    out.set(`${row.namespace}\u0000${row.identifier}`, Number(row.entity_id));
 377	  }
 378	  return out;
 379	}
 380	
 381	/**
 382	 * Resolve a link's identities onto at most one entity, honouring identity tiers.
 383	 *
 384	 * A present `primary` identity (immutable, e.g. `github_user_id`) is
 385	 * authoritative: it governs even when it matches nothing (a new account), so a
 386	 * stale non-primary like a reused `github_login` can't merge a fresh account
 387	 * into the old person. Without a primary, identities match equal-weight (the
 388	 * cross-channel WhatsApp/email matching relies on this).
 389	 *
 390	 * This is the single definition of that rule. It is deliberately shared by both
 391	 * resolution sites: the ordinary lookup AND the orphan-recovery re-resolution
 392	 * after a lost auto-create race. Those two used to carry separate copies and the
 393	 * recovery copy was tier-blind, which mis-resolved whenever a primary's owner
 394	 * was soft-deleted while a live entity held a recycled secondary claim — the
 395	 * link landed on the recycled-claim holder. `member_of` is a read ACL, so that
 396	 * handed one person another person's channel access.
 397	 *
 398	 * Returns the entity id when exactly one candidate survives, `null` when
 399	 * nothing matched at the governing tier, and `'ambiguous'` when several
 400	 * entities tied there — callers must fail closed on `'ambiguous'` and never
 401	 * pick one.
 402	 */
 403	function resolveIdentityTier(
 404	  identities: ResolvedIdentity[],
 405	  matches: Map<string, number>
 406	): number | null | 'ambiguous' {
 407	  const primaries = identities.filter((i) => i.primary);
 408	  // A present primary governs alone; otherwise every identity votes equally.
 409	  const governing = primaries.length > 0 ? primaries : identities;
 410	  const hits = new Set<number>();
 411	  for (const id of governing) {
 412	    const h = matches.get(`${id.namespace}\u0000${id.identifier}`);
 413	    if (h !== undefined) hits.add(h);
 414	  }
 415	  if (hits.size > 1) return 'ambiguous';
 416	  if (hits.size === 1) return [...hits][0];
 417	  return null;
 418	}
 419	
 420	function firstIdentityHit(
 421	  identities: ResolvedIdentity[],
 422	  matches: Map<string, number>
 423	): number | null {
 424	  for (const id of identities) {
 425	    const hit = matches.get(`${id.namespace}\u0000${id.identifier}`);
 426	    if (hit !== undefined) return hit;
 427	  }
 428	  return null;
 429	}
 430	
 431	async function createEntityWithIdentities(
 432	  sql: DbClient,
 433	  params: {
 434	    orgId: string;
 435	    connectorKey: string;
 436	    connectionId?: number | null;
 437	    entityType: string;
 438	    title: string;
 439	    identities: ExtractedLink['identities'];
 440	    traits: Map<string, unknown>;
 441	    creatorUserId: string;
 442	  }
 443	): Promise<{ entityId: number; attached: Array<{ namespace: string; identifier: string }> } | null> {
 444	  const persisted = params.identities.filter((i) => !i.matchOnly);
 445	  if (persisted.length === 0) return null;
 446	
 447	  const name = params.title || persisted[0].identifier;
 448	  const metadata: Record<string, unknown> = {};
 449	  for (const [key, value] of params.traits) metadata[key] = value;
 450	
 451	  // Resolve entity_type slug → entity_types(id). Same schema search path as
 452	  // createEntity: try the entity's own org first, then any visibility='public'
 453	  // catalog. First match wins. See createEntity for the slug-poisoning caveat.
 454	  let typeRow = await sql<{ id: number; backing_sql: string | null }>`
 455	    SELECT et.id, et.backing_sql
 456	    FROM entity_types et
 457	    LEFT JOIN organization o ON o.id = et.organization_id
 458	    WHERE et.slug = ${params.entityType}
 459	      AND et.deleted_at IS NULL
 460	      AND (
 461	        et.organization_id = ${params.orgId}
 462	        OR o.visibility = 'public'
 463	      )
 464	    ORDER BY (et.organization_id = ${params.orgId}) DESC, et.id ASC
 465	    LIMIT 1
 466	  `;
 467	  if (typeRow.length === 0) {
 468	    // Platform ACL type is ensured on the fly so event attribution can race
 469	    // ahead of the first ACL sync without failing closed on a missing type.
 470	    if (params.entityType === ACL_RESOURCE_TYPE_SLUG) {
 471	      await ensureResourceEntityType(params.orgId);
 472	      typeRow = await sql<{ id: number; backing_sql: string | null }>`
 473	        SELECT et.id, et.backing_sql
 474	        FROM entity_types et
 475	        WHERE et.slug = ${params.entityType}
 476	          AND et.deleted_at IS NULL
 477	          AND et.organization_id = ${params.orgId}
 478	        LIMIT 1
 479	      `;
 480	      if (typeRow.length === 0) {
 481	        logger.warn(
 482	          { entityType: params.entityType, orgId: params.orgId },
 483	          'entity create failed: $resource type ensure did not materialize'
 484	        );
 485	        return null;
 486	      }
 487	    } else {
 488	      logger.warn(
 489	        { entityType: params.entityType, orgId: params.orgId },
 490	        'entity create failed: unknown entity type'
 491	      );
 492	      return null;
 493	    }
 494	  }
 495	  // Derived (view-backed) types have no stored rows — skip auto-create (the
 496	  // view ignores any row this would insert). Mirrors createEntity's guard for
 497	  // this separate connector/link insert path.
 498	  if (typeRow[0].backing_sql) {
 499	    logger.warn(
 500	      { entityType: params.entityType, orgId: params.orgId },
 501	      'entity auto-create skipped: entity type is derived (a SQL view)'
 502	    );
 503	    return null;
 504	  }
 505	  const entityTypeId = typeRow[0].id;
 506	
 507	  // Try a few slug variants to defuse improbable random collisions.
 508	  let entityId: number | null = null;
 509	  for (let attempt = 0; attempt < 3 && entityId === null; attempt++) {
 510	    const slug = randomSlug(params.entityType);
 511	    const inserted = await tryInsertEntityRow({
 512	      tx: sql,
 513	      row: {
 514	        organizationId: params.orgId,
 515	        entityTypeId,
 516	        name,
 517	        slug,
 518	        metadata,
 519	        createdBy: params.creatorUserId,
 520	      },
 521	    });
 522	    if (inserted) entityId = Number(inserted.id);
 523	  }
 524	  if (entityId === null) return null;
 525	
 526	  const attached = await insertIdentities(sql, {
 527	    orgId: params.orgId,
 528	    entityId,
 529	    connectorKey: params.connectorKey,
 530	    connectionId: params.connectionId,
 531	    identities: persisted,
 532	  });
 533	  // Seed metadata.aliases from the identifiers that actually attached, so the
 534	  // metric compiler (which resolves event fields against metadata->'aliases')
 535	  // can attribute this contact's events from the moment it's created.
 536	  await ensureAliases(sql, {
 537	    orgId: params.orgId,
 538	    entityId,
 539	    identifiers: attached.map((a) => a.identifier),
 540	  });
 580	async function applyTraits(
 581	  sql: DbClient,
 582	  params: {
 583	    orgId: string;
 584	    entityId: number;
 585	    rule: ResolvedEventAttributionRule;
