1034	export async function resolveSenderIdentity(
1035	  sql: DbClient,
1036	  params: SenderIdentityParams
1037	): Promise<number | null> {
1038	  if (params.identities.length === 0) return null;
1039	  // Every captured message calls this, and the overwhelming majority resolve a
1040	  // sender that already exists — answer those from a plain read rather than
1041	  // opening a write transaction per message. Only a miss (which may mint) needs
1042	  // one, and the in-transaction path re-runs this lookup because a concurrent
1043	  // mint can land between the two.
1044	  const existing = firstIdentityHit(
1045	    params.identities,
1046	    await lookupMatches(sql, { orgId: params.orgId, identities: [params.identities] })
1047	  );
