1065	  const creatorUserId = await resolveOrgCreator(params.orgId);
1066	  if (!creatorUserId) return null;
1067	
1068	  const created = await createEntityWithIdentities(sql, {
1069	    orgId: params.orgId,
1070	    connectorKey: params.connectorKey,
1071	    entityType: params.mintEntityType,
1072	    title: params.title?.trim() || '',
1073	    identities: params.identities,
1074	    traits: new Map(),
1075	    creatorUserId,
1076	  });
1077	  if (created !== null && created.attached.length > 0) {
1078	    return created.entityId;
1079	  }
1080	  // Lost the identity create-race (a concurrent ingest minted it first): drop
1081	  // the identity-less orphan and resolve to the winner instead.
1082	  if (created !== null) {
