144	/**
145	 * Validate that the relationship type allows the given entity type pair.
146	 * For symmetric types, checks both directions.
147	 */
148	export async function validateTypeRule(
149	  relationshipTypeId: number,
150	  fromEntityId: number,
151	  toEntityId: number,
152	  sql: DbClient
153	): Promise<void> {
154	  // Get the relationship type to check if it's symmetric
155	  const typeRows = await sql`
156	    SELECT is_symmetric
157	    FROM entity_relationship_types
158	    WHERE id = ${relationshipTypeId}
159	      AND deleted_at IS NULL
160	  `;
161	  if (typeRows.length === 0) {
162	    throw new ToolUserError(`Relationship type ${relationshipTypeId} not found`, 404);
163	  }
164	  const isSymmetric = Boolean(typeRows[0].is_symmetric);
165	
166	  // Get entity types for both entities
167	  const entityRows = await sql`
168	    SELECT e.id, et.slug AS entity_type
169	    FROM entities e
170	    JOIN entity_types et ON et.id = e.entity_type_id
171	    WHERE e.id IN (${fromEntityId}, ${toEntityId})
172	  `;
173	  const fromEntityType = String(entityRows.find((r) => Number(r.id) === fromEntityId)?.entity_type);
174	  const toEntityType = String(entityRows.find((r) => Number(r.id) === toEntityId)?.entity_type);
175	
176	  // Check if there are any rules for this relationship type
177	  const ruleRows = await sql`
178	    SELECT source_entity_type_slug, target_entity_type_slug
179	    FROM entity_relationship_type_rules
180	    WHERE relationship_type_id = ${relationshipTypeId}
181	      AND deleted_at IS NULL
182	  `;
183	
184	  // No rules = any pair is allowed
185	  if (ruleRows.length === 0) return;
186	
187	  // Check if the pair matches any rule (check both directions for symmetric types)
188	  const matches = ruleRows.some((rule) => {
189	    const srcSlug = String(rule.source_entity_type_slug);
190	    const tgtSlug = String(rule.target_entity_type_slug);
191	
192	    if (srcSlug === fromEntityType && tgtSlug === toEntityType) return true;
193	    if (isSymmetric && srcSlug === toEntityType && tgtSlug === fromEntityType) return true;
194	    return false;
195	  });
196	
197	  if (!matches) {
198	    throw new ToolUserError(
199	      `Relationship type ${relationshipTypeId} does not allow ${fromEntityType} → ${toEntityType}`,
200	      400
201	    );
202	  }
203	}
