  1	/**
  2	 * SPIKE — edges as a claim set plus an append-only change log.
  3	 *
  4	 * The design: every assertion and retraction is recorded in the log (what
  5	 * changed and how); `entity_relationships` stays the projection holding current
  6	 * state (what is true now, at index speed).
  7	 *
  8	 * This is NOT a new architecture. Entity *field* changes already work this way —
  9	 * `recordChangeEvent` writes a field-level diff into `events` with
 10	 * `semantic_type='change'` while the entity row holds current state. Edges are
 11	 * the hole in that pattern: on origin/main `recordChangeEvent` has exactly one
 12	 * call site (`manage_entity.ts:574`, inside `handleUpdate`), and `handleLink`,
 13	 * `handleUnlink` and `handleUpdateLink` record nothing at all.
 14	 *
 15	 * The one novel piece is WHERE current claim state lives. Folding the whole log
 16	 * to answer "is this edge live" would be an aggregate over history, which the
 17	 * read path forbids and which grows without bound. So the projection row carries
 18	 * its own claim set in `metadata.claims`, keyed by owner — bounded by the number
 19	 * of owners, never by history length. The log is written for audit and replay
 20	 * and is never read to decide current state.
 21	 */
 22	import type { DbClient } from '../db/client';
 23	import { getDb } from '../db/client';
 24	import { insertConnectionlessAuditEvent, stableJson } from './insert-event';
 25	
 26	/**
 27	 * Edge changes ride the existing `semantic_type='change'` bucket, discriminated
 28	 * by `metadata.category`, exactly as deployment and lifecycle audits already do.
 29	 * This matches what shipped in #2807 for the MCP link handlers, so a reader sees
 30	 * one contract whether a human or a connector moved the edge.
 31	 */
 32	export const EDGE_CHANGE_SEMANTIC_TYPE = 'change';
 33	export const EDGE_CHANGE_CATEGORY = 'relationship';
 34	
 35	export type EdgeClaimRef = {
 36	  orgId: string;
 37	  fromEntityId: number;
 38	  toEntityId: number;
 39	  relationshipTypeId: number;
 40	  /** Stable owner identity — a connector rule, a user, an agent. */
 41	  ownerId: string;
 42	};
 43	
 44	export type ClaimOutcome = {
 45	  /** Live after this operation. */
 46	  live: boolean;
 47	  /** Owners currently asserting this edge. */
 48	  owners: string[];
 49	  /** The projection changed state (created or tombstoned), rather than only its claim set. */
 50	  flipped: boolean;
 51	};
 52	
 53	function claimsOf(metadata: unknown): string[] {
 54	  const claims = (metadata as { claims?: Record<string, unknown> } | null)?.claims;
 55	  return claims ? Object.keys(claims).sort() : [];
 56	}
 57	
 58	/**
 59	 * Append the change to the log — but ONLY when the claim set actually moved.
 60	 *
 61	 * This guard is what makes the log affordable at connector scale. A sync
 62	 * re-asserts every edge it still believes in, so without it a 10k-edge feed
 63	 * would append 10k audit rows per run to an append-only table, for a graph that
 64	 * did not change. Re-asserting an existing claim is a no-op and records
 65	 * nothing; a new row, a new co-owner, or a withdrawal all move the set and are
 66	 * all recorded.
 67	 *
 68	 * A dropped row costs history, never state: current ownership lives in the
 69	 * projection row's claim set, which is the same reason the shipped edge audit
 70	 * tolerates a drop.
 71	 */
 72	async function logEdgeChange(params: {
 73	  ref: EdgeClaimRef;
 74	  op: 'assert' | 'retract';
 75	  before: string[];
 76	  after: string[];
 77	  ruleVersion?: string;
 78	  seq: string;
 79	}): Promise<void> {
 80	  const { ref } = params;
 81	  if (stableJson(params.before) === stableJson(params.after)) return;
 82	  await insertConnectionlessAuditEvent({
 83	    organizationId: ref.orgId,
 84	    entityIds: [ref.fromEntityId, ref.toEntityId],
 85	    // Idempotency is keyed on the caller-supplied sequence token, so a retried
 86	    // batch does not append a second identical history row.
 87	    originId: `edge:${ref.fromEntityId}:${ref.toEntityId}:${ref.relationshipTypeId}:${ref.ownerId}:${params.seq}`,
 88	    semanticType: EDGE_CHANGE_SEMANTIC_TYPE,
 89	    title: `Relationship ${params.op === 'assert' ? 'claimed' : 'released'}: ${ref.fromEntityId}->${ref.toEntityId}`,
 90	    metadata: {
 91	      _lobu_relationship_change: true,
 92	      category: EDGE_CHANGE_CATEGORY,
 93	      op: params.op,
 94	      ownerId: ref.ownerId,
 95	      fromEntityId: String(ref.fromEntityId),
 96	      toEntityId: String(ref.toEntityId),
 97	      relationshipTypeId: String(ref.relationshipTypeId),
 98	      ruleVersion: params.ruleVersion ?? null,
 99	      // The diff, in the same `changes = [{field, old, new}]` shape the MCP
100	      // handlers write, so one reader parses both.
101	      changes: [{ field: 'claims', old: params.before, new: params.after }],
102	    },
103	  });
104	}
105	
106	/**
107	 * Record that `ownerId` asserts this edge. Idempotent per owner: asserting twice
108	 * leaves one claim.
109	 *
110	 * The claim-set mutation is ONE statement, so concurrent owners serialize on the
111	 * projection row's lock rather than racing a read-modify-write.
112	 */
113	export async function assertEdgeClaim(params: {
114	  ref: EdgeClaimRef;
115	  ruleVersion?: string;
116	  createdBy: string;
117	  seq: string;
118	  sql?: DbClient;
119	}): Promise<ClaimOutcome> {
120	  const run = async (sql: DbClient): Promise<ClaimOutcome> => {
121	    const { ref } = params;
122	    const claimValue = { ruleVersion: params.ruleVersion ?? null };
123	
124	    const before = await sql<{ metadata: unknown }>`
125	      SELECT metadata FROM entity_relationships
126	      WHERE organization_id = ${ref.orgId}
127	        AND from_entity_id = ${ref.fromEntityId}
128	        AND to_entity_id = ${ref.toEntityId}
129	        AND relationship_type_id = ${ref.relationshipTypeId}
130	        AND deleted_at IS NULL
131	      FOR UPDATE
132	    `;
133	    const beforeOwners = before.length > 0 ? claimsOf(before[0].metadata) : [];
134	
135	    const rows = await sql<{ metadata: unknown; inserted: number }>`
136	      INSERT INTO entity_relationships (
137	        organization_id, from_entity_id, to_entity_id, relationship_type_id,
138	        metadata, confidence, source, created_by, updated_by, created_at, updated_at
139	      ) VALUES (
140	        ${ref.orgId}, ${ref.fromEntityId}, ${ref.toEntityId}, ${ref.relationshipTypeId},
141	        ${sql.json({ claims: { [ref.ownerId]: claimValue } })},
142	        1.0, 'feed', ${params.createdBy}, ${params.createdBy},
143	        current_timestamp, current_timestamp
144	      )
145	      ON CONFLICT (from_entity_id, to_entity_id, relationship_type_id)
146	        WHERE deleted_at IS NULL
147	      DO UPDATE SET
148	        metadata = jsonb_set(
149	          coalesce(entity_relationships.metadata, '{}'::jsonb),
150	          ARRAY['claims', ${ref.ownerId}],
151	          ${sql.json(claimValue)},
152	          true
153	        ),
154	        updated_by = ${params.createdBy},
155	        updated_at = current_timestamp
156	      RETURNING metadata,
157	                -- Did THIS statement insert the row, or update an existing one?
158	                -- The pre-read cannot answer that: under a race both callers
159	                -- read "no row" and both would claim the create. xmax is zero
160	                -- only on a genuinely new tuple.
161	                (xmax = 0)::int AS inserted
162	    `;
163	    const afterOwners = claimsOf(rows[0]?.metadata);
164	    await logEdgeChange({
165	      ref,
166	      op: 'assert',
167	      before: beforeOwners,
168	      after: afterOwners,
169	      ruleVersion: params.ruleVersion,
170	      seq: params.seq,
171	    });
172	    return { live: true, owners: afterOwners, flipped: Number(rows[0]?.inserted) === 1 };
173	  };
174	  return params.sql ? run(params.sql) : (getDb().begin(run) as Promise<ClaimOutcome>);
175	}
176	
177	/**
178	 * Withdraw `ownerId`'s claim. The edge is tombstoned only when the LAST claim
179	 * goes — which is the whole point: one owner withdrawing must not destroy an
180	 * edge another owner still asserts.
181	 */
182	export async function retractEdgeClaim(params: {
183	  ref: EdgeClaimRef;
184	  seq: string;
185	  sql?: DbClient;
186	}): Promise<ClaimOutcome> {
187	  const run = async (sql: DbClient): Promise<ClaimOutcome> => {
188	    const { ref } = params;
189	    const before = await sql<{ metadata: unknown }>`
190	      SELECT metadata FROM entity_relationships
191	      WHERE organization_id = ${ref.orgId}
192	        AND from_entity_id = ${ref.fromEntityId}
193	        AND to_entity_id = ${ref.toEntityId}
194	        AND relationship_type_id = ${ref.relationshipTypeId}
195	        AND deleted_at IS NULL
196	      FOR UPDATE
197	    `;
198	    if (before.length === 0) return { live: false, owners: [], flipped: false };
199	    const beforeOwners = claimsOf(before[0].metadata);
200	
201	    // Remove this owner's key, and tombstone in the SAME statement iff nothing
202	    // remains. Column references on the right-hand side see the pre-update row,
203	    // so the emptiness test is evaluated against the old claim set.
204	    const rows = await sql<{ metadata: unknown; deleted_at: string | null }>`
205	      UPDATE entity_relationships
206	      SET metadata = jsonb_set(
207	            coalesce(metadata, '{}'::jsonb),
208	            ARRAY['claims'],
209	            coalesce(metadata -> 'claims', '{}'::jsonb) - ${ref.ownerId},
210	            true
211	          ),
212	          deleted_at = CASE
213	            WHEN (coalesce(metadata -> 'claims', '{}'::jsonb) - ${ref.ownerId}) = '{}'::jsonb
214	            THEN current_timestamp ELSE NULL END,
215	          updated_at = current_timestamp
216	      WHERE organization_id = ${ref.orgId}
217	        AND from_entity_id = ${ref.fromEntityId}
218	        AND to_entity_id = ${ref.toEntityId}
219	        AND relationship_type_id = ${ref.relationshipTypeId}
220	        AND deleted_at IS NULL
221	      RETURNING metadata, deleted_at
222	    `;
223	    const afterOwners = claimsOf(rows[0]?.metadata);
224	    const live = rows[0]?.deleted_at == null;
225	    await logEdgeChange({
226	      ref,
227	      op: 'retract',
228	      before: beforeOwners,
229	      after: afterOwners,
230	      seq: params.seq,
231	    });
232	    return { live, owners: afterOwners, flipped: live === false };
233	  };
234	  return params.sql ? run(params.sql) : (getDb().begin(run) as Promise<ClaimOutcome>);
235	}
236	
237	export type EdgeHistoryEntry = {
238	  op: string;
239	  ownerId: string;
240	  before: string[];
241	  after: string[];
242	  occurredAt: string;
243	};
244	
245	/**
246	 * Read the change history for one edge. AUDIT ONLY — never a read path. Current
247	 * state comes from the projection row's claim set, which is why this can be a
248	 * full history scan without violating the no-aggregate-on-read rule.
249	 */
250	export async function readEdgeHistory(params: {
251	  orgId: string;
252	  fromEntityId: number;
253	  toEntityId: number;
254	  relationshipTypeId: number;
255	  sql?: DbClient;
256	}): Promise<EdgeHistoryEntry[]> {
257	  const sql = params.sql ?? getDb();
258	  const rows = await sql<
259	    {
260	      op: string;
261	      owner_id: string;
262	      changes: Array<{ old: string[]; new: string[] }>;
263	      occurred_at: string;
264	    }
265	  >`
266	    SELECT metadata ->> 'op' AS op,
267	           metadata ->> 'ownerId' AS owner_id,
268	           metadata -> 'changes' AS changes,
269	           occurred_at
270	    FROM events
271	    WHERE organization_id = ${params.orgId}
272	      AND semantic_type = ${EDGE_CHANGE_SEMANTIC_TYPE}
273	      AND metadata ? '_lobu_relationship_change'
274	      AND metadata ->> 'category' = ${EDGE_CHANGE_CATEGORY}
275	      AND metadata ->> 'fromEntityId' = ${String(params.fromEntityId)}
276	      AND metadata ->> 'toEntityId' = ${String(params.toEntityId)}
277	      AND metadata ->> 'relationshipTypeId' = ${String(params.relationshipTypeId)}
278	    ORDER BY id ASC
279	  `;
280	  return rows.map((r) => ({
281	    op: r.op,
282	    ownerId: r.owner_id,
283	    before: r.changes?.[0]?.old ?? [],
284	    after: r.changes?.[0]?.new ?? [],
285	    occurredAt: r.occurred_at,
286	  }));
287	}
  1	/**
  2	 * SPIKE — the connector-facing half of connector-declared entity->entity edges.
  3	 *
  4	 * NOT production placement. This exists to answer one question with running
  5	 * code rather than a design document: what does a connector actually write in
  6	 * its manifest, and how much new machinery does honouring it require?
  7	 *
  8	 * The answer is that it requires almost none. Both endpoints of an
  9	 * entity->entity edge resolve through the SAME identity machinery that
 10	 * `attributions` already uses today. So the materializer is a thin layer over
 11	 * resolution that already happens on every sync — resolve twice instead of
 12	 * once, then write one row.
 13	 *
 14	 * The declaration below deliberately mirrors `EventAttributionRule`: same
 15	 * target spec, same `autoCreate`, same identity selectors. A connector author
 16	 * who can write `attributions` can already write this.
 17	 */
 18	import type { EntityIdentitySpec } from '@lobu/connector-sdk';
 19	import type { DbClient } from '../db/client';
 20	import { getDb, pgBigintArray } from '../db/client';
 21	import { assertEdgeClaim, retractEdgeClaim } from './edge-claims-spike';
 22	import { normalizeIdentityValue } from './entity-link-upsert';
 23	import { canonicalizeSymmetricEdge, validateTypeRule } from './relationship-validation';
 24	
 25	/**
 26	 * Proposed manifest shape, additive on `feeds_schema[feed].eventKinds[kind]`:
 27	 *
 28	 * ```ts
 29	 * eventKinds: {
 30	 *   invoice: {
 31	 *     attributions: [ ... ],            // event -> entity, unchanged
 32	 *     relationships: [                  // entity -> entity, new
 33	 *       {
 34	 *         type: 'invoice_customer',
 35	 *         from: { entityType: 'invoice',  identities: [{ namespace: 'erp_invoice',  eventPath: 'metadata.origin_id' }] },
 36	 *         to:   { entityType: 'customer', identities: [{ namespace: 'erp_customer', eventPath: 'metadata.customer_origin_id' }] },
 37	 *       },
 38	 *     ],
 39	 *   },
 40	 * }
 41	 * ```
 42	 */
 43	export type DeclaredEdgeEndpoint = {
 44	  entityType: string;
 45	  identities: EntityIdentitySpec[];
 46	};
 47	
 48	export type DeclaredEdgeRule = {
 49	  /** Relationship type slug. Resolved against the DB, never trusted from the caller. */
 50	  type: string;
 51	  /**
 52	   * Stable name for this rule within its connector manifest. Together with the
 53	   * connection it forms the edge's OWNER identity — the thing reconcile is
 54	   * scoped to. Deliberately independent of `ruleVersion`: an author bumping the
 55	   * version must keep owning the edges the previous version wrote, or they
 56	   * strand.
 57	   */
 58	  name: string;
 59	  from: DeclaredEdgeEndpoint;
 60	  to: DeclaredEdgeEndpoint;
 61	};
 62	
 63	/** `connectionId:ruleName` — stable across rule-version bumps. */
 64	function ownerIdOf(connectionId: number, ruleName: string): string {
 65	  return `${connectionId}:${ruleName}`;
 66	}
 67	
 68	function valueAtPath(item: Record<string, unknown>, path: string): string | null {
 69	  let cur: unknown = item;
 70	  for (const seg of path.split('.')) {
 71	    if (cur == null || typeof cur !== 'object') return null;
 72	    cur = (cur as Record<string, unknown>)[seg];
 73	  }
 74	  if (cur == null) return null;
 75	  const s = String(cur).trim();
 76	  return s === '' ? null : s;
 77	}
 78	
 79	/**
 80	 * Resolve one endpoint to an entity id through `entity_identities` — the same
 81	 * table `attributions` writes. Returns null when nothing resolves, which is the
 82	 * caller's signal to skip rather than to park state: the attribution pass with
 83	 * `autoCreate` is what guarantees the row exists by the time this runs.
 84	 */
 85	async function resolveEndpoint(
 86	  sql: DbClient,
 87	  orgId: string,
 88	  endpoint: DeclaredEdgeEndpoint,
 89	  item: Record<string, unknown>
 90	): Promise<number | null> {
 91	  for (const spec of endpoint.identities) {
 92	    const raw = valueAtPath(item, spec.eventPath);
 93	    if (!raw) continue;
 94	    // The SAME function the attribution path used to store this identity.
 95	    // Re-implementing it (a bare trim) silently misses every normalized
 96	    // namespace — an email stored lowercase is never found by its raw form.
 97	    const identifier = normalizeIdentityValue(spec.namespace, raw);
 98	    if (!identifier) continue;
 99	    // Joined to the entity's TYPE, because `endpoint.entityType` is part of the
100	    // declaration and must constrain what resolves. Matching on the identity
101	    // alone would let a manifest that says `from: invoice` quietly attach the
102	    // edge to whatever entity happens to hold that identifier.
103	    const rows = await sql<{ entity_id: number }>`
104	      SELECT ei.entity_id
105	      FROM entity_identities ei
106	      JOIN entities e ON e.id = ei.entity_id
107	      JOIN entity_types et ON et.id = e.entity_type_id
108	      WHERE ei.organization_id = ${orgId}
109	        AND ei.namespace = ${spec.namespace}
110	        AND ei.identifier = ${identifier}
111	        AND ei.deleted_at IS NULL
112	        AND e.deleted_at IS NULL
113	        AND et.slug = ${endpoint.entityType}
114	      LIMIT 1
115	    `;
116	    if (rows.length > 0) return Number(rows[0].entity_id);
117	  }
118	  return null;
119	}
120	
121	/**
122	 * Resolve the relationship type FROM THE DB, never from the manifest string
123	 * alone — the `$links` gate decision requires exactly this, so that a connector
124	 * cannot name an authz-bearing type into existence.
125	 */
126	async function resolveRelationshipType(
127	  sql: DbClient,
128	  orgId: string,
129	  slug: string
130	): Promise<{ id: number; isSymmetric: boolean } | null> {
131	  const rows = await sql<{ id: number; is_symmetric: boolean }>`
132	    SELECT id, is_symmetric FROM entity_relationship_types
133	    WHERE organization_id = ${orgId} AND slug = ${slug}
134	      AND status = 'active' AND deleted_at IS NULL
135	    LIMIT 1
136	  `;
137	  return rows.length > 0
138	    ? { id: Number(rows[0].id), isSymmetric: Boolean(rows[0].is_symmetric) }
139	    : null;
140	}
141	
142	export type MaterializeResult = {
143	  created: number;
144	  duplicate: number;
145	  unresolved: number;
146	  unknownType: number;
147	  /** Live edges withdrawn because the batch no longer asserts them. */
148	  retracted: number;
149	  /**
150	   * Resolved to a real pair, but the org's `entity_relationship_type_rules`
151	   * forbid that type pairing. Counted rather than thrown: one bad item in a
152	   * 10k-item sync must not abort the batch.
153	   */
154	  rejected: number;
155	};
156	
157	/**
158	 * Honour a feed's declared edge rules for a batch of synced items.
159	 *
160	 * Runs AFTER the attribution pass, so both endpoints already exist.
161	 *
162	 * Writes its provenance as a CLAIM under `metadata.claims[ownerId]` rather than
163	 * as a single `metadata.derivedFrom` owner. The single-owner shape could not
164	 * represent one edge that two sources both assert, so a connector's reconcile
165	 * destroyed edges a human or a second connector still stood behind. The claim
166	 * set is bounded by the number of owners, never by history length, so it stays
167	 * an indexed read.
168	 */
169	export async function materializeDeclaredEdges(params: {
170	  orgId: string;
171	  connectionId: number;
172	  ruleVersion: string;
173	  rules: DeclaredEdgeRule[];
174	  items: Array<Record<string, unknown>>;
175	  createdBy: string;
176	  /**
177	   * Identifies THIS sync attempt. Stable across a retry of the same batch (so a
178	   * replay appends no duplicate history) and distinct between genuine runs (so
179	   * a real later change is not mistaken for a replay of the earlier one).
180	   */
181	  syncToken: string;
182	  /**
183	   * Withdraw edges this rule previously asserted from a from-entity that the
184	   * CURRENT batch also touches, but no longer points at the same target — the
185	   * "the invoice moved to a different customer" case. Scoped to the batch's own
186	   * from-entities, so a partial sync never retracts what it did not observe.
187	   */
188	  reconcile?: boolean;
189	  sql?: DbClient;
190	}): Promise<MaterializeResult> {
191	  // Insert and reconcile are ONE logical operation and must be atomic. Run as
192	  // separate autocommitted statements, two replicas processing conflicting
193	  // batches for the same from-entity destroy each other's work: A inserts, B
194	  // inserts, A's reconcile removes B's edge, B's reconcile removes A's, and the
195	  // invoice is left with NO customer at all. Silent data loss, reproduced in
196	  // `declared-edges-concurrency.test.ts`. Inside a transaction the two
197	  // serialize and the later writer simply wins.
198	  //
199	  // A caller-supplied handle is assumed to already be a transaction (the sync
200	  // path threads its own), so we never nest.
201	  if (!params.sql) {
202	    return getDb().begin((tx) => materializeDeclaredEdges({ ...params, sql: tx as DbClient })) as
203	      Promise<MaterializeResult>;
204	  }
205	  const sql = params.sql;
206	  const out: MaterializeResult = {
207	    created: 0,
208	    duplicate: 0,
209	    unresolved: 0,
210	    unknownType: 0,
211	    retracted: 0,
212	    rejected: 0,
213	  };
214	
215	  for (const rule of params.rules) {
216	    const relType = await resolveRelationshipType(sql, params.orgId, rule.type);
217	    if (relType == null) {
218	      out.unknownType += params.items.length;
219	      continue;
220	    }
221	    const typeId = relType.id;
222	    /** from_entity_id -> the to_entity_ids THIS batch asserts for it. */
223	    const asserted = new Map<number, Set<number>>();
224	    for (const item of params.items) {
225	      const resolvedFrom = await resolveEndpoint(sql, params.orgId, rule.from, item);
226	      const resolvedTo = await resolveEndpoint(sql, params.orgId, rule.to, item);
227	      if (resolvedFrom == null || resolvedTo == null || resolvedFrom === resolvedTo) {
228	        out.unresolved += 1;
229	        continue;
230	      }
231	      // A symmetric type must land on ONE canonical ordering, or a connector
232	      // that happens to emit b->a creates a second edge for the same fact and
233	      // the claim set is split across two rows that never converge.
234	      const { from: fromId, to: toId } = relType.isSymmetric
235	        ? canonicalizeSymmetricEdge(resolvedFrom, resolvedTo)
236	        : { from: resolvedFrom, to: resolvedTo };
237	
238	      // The SAME type-pair rules the MCP link path enforces. Without this a
239	      // connector manifest can assert pairings an operator explicitly forbade.
240	      try {
241	        await validateTypeRule(typeId, fromId, toId, sql);
242	      } catch {
243	        out.rejected += 1;
244	        continue;
245	      }
246	      // A claim, not a bare insert. Two owners asserting the same triple share
247	      // ONE projection row and each hold their own key in `metadata.claims`,
248	      // which is what stops this connector's reconcile from destroying an edge
249	      // a human or another connector still asserts.
250	      const outcome = await assertEdgeClaim({
251	        ref: {
252	          orgId: params.orgId,
253	          fromEntityId: fromId,
254	          toEntityId: toId,
255	          relationshipTypeId: typeId,
256	          ownerId: ownerIdOf(params.connectionId, rule.name),
257	        },
258	        ruleVersion: params.ruleVersion,
259	        createdBy: params.createdBy,
260	        // Stable per sync, so a retried batch re-asserts without appending a
261	        // second identical history row.
262	        seq: params.syncToken,
263	        sql,
264	      });
265	      if (outcome.flipped) out.created += 1;
266	      else out.duplicate += 1;
267	      const set = asserted.get(fromId);
268	      if (set) set.add(toId);
269	      else asserted.set(fromId, new Set([toId]));
270	    }
271	
272	    if (!params.reconcile || asserted.size === 0) continue;
273	    // Every edge THIS OWNER derived, from a from-entity the batch observed,
274	    // whose target the batch no longer asserts. No separate state table is
275	    // consulted — the batch IS the snapshot, exactly as access-graph reconciles
276	    // departures.
277	    //
278	    // Scoped to `ownerId`, not `ruleVersion` and not the bare (from, type)
279	    // slice. Both alternatives are wrong in opposite directions: scoping to the
280	    // version strands every edge the previous version wrote the moment an
281	    // author bumps it, while scoping to nothing makes two owners delete each
282	    // other's edges on alternating syncs. Owner identity is stable across
283	    // version bumps and distinct between owners, so it is the only scope that
284	    // is right in both cases.
285	    //
286	    // A hand-authored (`source='ui'`) edge carries no `derivedFrom` and is
287	    // therefore never touched, which is the point of keying on it at all.
288	    for (const [fromId, targets] of asserted) {
289	      // Select what this owner still claims but no longer asserts, then release
290	      // each claim individually. A blanket UPDATE ... SET deleted_at would
291	      // tombstone the row out from under every co-owner; releasing a claim
292	      // tombstones only when it was the last one standing.
293	      const stale = await sql<{ to_entity_id: number }>`
294	        SELECT to_entity_id
295	        FROM entity_relationships
296	        WHERE organization_id = ${params.orgId}
297	          AND from_entity_id = ${fromId}
298	          AND relationship_type_id = ${typeId}
299	          AND deleted_at IS NULL
300	          AND metadata -> 'claims' ? ${ownerIdOf(params.connectionId, rule.name)}
301	          AND NOT (to_entity_id = ANY (${pgBigintArray([...targets])}::bigint[]))
302	      `;
303	      for (const row of stale) {
304	        await retractEdgeClaim({
305	          ref: {
306	            orgId: params.orgId,
307	            fromEntityId: fromId,
308	            toEntityId: Number(row.to_entity_id),
309	            relationshipTypeId: typeId,
310	            ownerId: ownerIdOf(params.connectionId, rule.name),
311	          },
312	          seq: params.syncToken,
313	          sql,
314	        });
315	        out.retracted += 1;
316	      }
317	    }
318	  }
319	  return out;
320	}
321	
322	/**
323	 * Withdraw every claim a rule version asserted, for one relationship type.
324	 *
325	 * Releases claims rather than tombstoning rows outright: an edge that a human
326	 * or a second connector also asserts must survive this rule being withdrawn,
327	 * and only the LAST claim going takes the row with it. The relationship type
328	 * comes from the column, not from metadata, so the type filter stays indexed.
329	 *
330	 * Returns the number of claims released, which is not necessarily the number of
331	 * edges that disappeared.
332	 */
333	export async function retractDeclaredEdges(params: {
334	  orgId: string;
335	  relationshipTypeId: number;
336	  ruleVersion: string;
337	  /** See `materializeDeclaredEdges` — stable across a retry of this withdrawal. */
338	  syncToken: string;
339	  sql?: DbClient;
340	}): Promise<number> {
341	  const sql = params.sql ?? getDb();
342	  const claims = await sql<{
343	    from_entity_id: number;
344	    to_entity_id: number;
345	    owner_id: string;
346	  }>`
347	    SELECT r.from_entity_id, r.to_entity_id, c.key AS owner_id
348	    FROM entity_relationships r,
349	         LATERAL jsonb_each(r.metadata -> 'claims') AS c
350	    WHERE r.organization_id = ${params.orgId}
351	      AND r.deleted_at IS NULL
352	      AND r.relationship_type_id = ${params.relationshipTypeId}
353	      AND c.value ->> 'ruleVersion' = ${params.ruleVersion}
354	  `;
355	  for (const claim of claims) {
356	    await retractEdgeClaim({
357	      ref: {
358	        orgId: params.orgId,
359	        fromEntityId: Number(claim.from_entity_id),
360	        toEntityId: Number(claim.to_entity_id),
361	        relationshipTypeId: params.relationshipTypeId,
362	        ownerId: claim.owner_id,
363	      },
364	      seq: params.syncToken,
365	      sql,
366	    });
367	  }
368	  return claims.length;
369	}

