230	  // Which entity a member's claims resolve to follows the tier semantics the
231	  // create path below (`resolveEventAttributionsForItems`) already implements —
232	  // see `primary` in connector-types.ts. Stopping at the first array hit made
233	  // the answer depend on the order a connector pushed its identities, and
234	  // `member_of` is a read ACL, so that was a mis-grant waiting to happen: a
235	  // stale or recycled secondary claim (an old email, a reused login) would hand
236	  // one person another person's channel access. A PRESENT primary identity —
237	  // the source's stable per-account key — therefore governs alone and never
238	  // falls through to a secondary match: a fresh primary means a distinct
239	  // account even when a recycled secondary still points at the old person.
240	  // This fast path only claims a member when its answer matches what the
241	  // create-path engine would decide; every other case (primary present but
242	  // unmatched, a same-tier conflict) falls through to `toCreate`, where that
243	  // engine mints a new entity keyed on the primary or refuses the ambiguous
244	  // match outright (no edge — fail closed) with its 'merge candidate' warning.
245	  const primaryNamespaces = new Set(
246	    memberIdentities.filter((s) => s.primary).map((s) => s.namespace)
247	  );
248	  const toCreate: AccessMember[] = [];
249	  for (const m of members) {
250	    const primaryHits = new Set<number>();
251	    const secondaryHits = new Set<number>();
252	    let primaryPresent = false;
253	    for (const id of m.identities) {
254	      if (!id.value) continue;
255	      const isPrimary = primaryNamespaces.has(id.namespace);
256	      if (isPrimary) primaryPresent = true;
257	      const found = existing.get(`${id.namespace}|${id.value}`);
258	      if (found === undefined) continue;
259	      (isPrimary ? primaryHits : secondaryHits).add(found);
260	    }
261	    let hit: number | undefined;
262	    if (primaryPresent) {
263	      if (primaryHits.size === 1) {
264	        hit = [...primaryHits][0];
265	        const overridden = [...secondaryHits].filter((id) => id !== hit);
266	        if (overridden.length > 0) {
267	          logger.warn(
268	            {
269	              organization_id: orgId,
270	              connector_key: connectorKey,
271	              member_key: m.key,
272	              resolved_to: hit,
273	              overridden_entity_ids: overridden,
274	            },
275	            'access-graph: member matched multiple entities — resolved via the primary identity'
276	          );
277	        }
278	      }
279	    } else if (secondaryHits.size === 1) {
280	      hit = [...secondaryHits][0];
281	    }
282	    if (hit !== undefined) byKey.set(m.key, hit);
283	    else toCreate.push(m);
284	  }
285	
286	  if (toCreate.length === 0) return byKey;
287	
288	  // Auto-create a `person` for each genuinely-new member, carrying ALL their
289	  // declared identities so a later source (or login) collapses onto them.
290	  const items = toCreate.map((m) => {
291	    const metadata: Record<string, unknown> = { display_name: m.name ?? m.key };
292	    for (const id of m.identities) metadata[id.namespace] = id.value;
293	    return { origin_type: 'access_member', metadata };
294	  });
295	  const resolved = await resolveEventAttributionsForItems({
296	    connectorKey,
297	    connectionId,
298	    orgId,
299	    items,
300	    rules: {
301	      access_member: [
