309	            eventPath: `metadata.${spec.namespace}`,
310	            primary: spec.primary,
311	          })),
312	        },
313	      ],
314	    },
315	  });
316	  for (let i = 0; i < toCreate.length; i++) {
317	    const ids = resolved.get(i);
318	    if (ids && ids.length > 0) byKey.set(toCreate[i].key, ids[0]);
319	  }
320	  return byKey;
321	}
