323	/**
324	 * Materialize a source's resource→audience graph and mark the connection
325	 * ACL-enforced. The CALLER normalizes its raw API shape into `resources`
326	 * (Slack channels with `T:C`/`T:U` keys, GitHub repos with collaborators, …);
327	 * this body is source-agnostic.
328	 */
329	export async function buildAccessGraph(params: {
330	  organizationId: string;
331	  connectionId: string;
332	  connectorKey: string;
333	  /** Identity namespace for resource keys (e.g. `slack_channel_id`). */
334	  resourceNamespace: string;
335	  memberIdentities: AccessIdentitySpec[];
336	  resources: AccessResource[];
337	  /**
338	   * Database time captured before the source snapshot began. A newer ACL-state
339	   * write means that snapshot lost a revocation race and must not mark the
340	   * connection fresh.
341	   */
342	  syncStartedAt?: string;
343	  /**
344	   * Whether this build may stamp the connection fresh. Default true — one build
345	   * IS the whole connection for a single-scope source (GitHub). A caller that
346	   * loops several scopes over one connection passes false and calls
347	   * `markAclFresh` itself after the last scope; see that function.
348	   */
349	  markFresh?: boolean;
350	}): Promise<AccessGraphResult> {
351	  const { organizationId, connectionId, connectorKey, resourceNamespace, memberIdentities } =
352	    params;
353	  const resources = params.resources.filter((r) => r.key);
354	  if (resources.length === 0) return EMPTY_RESULT;
355	
356	  const syncStartedAt =
357	    params.syncStartedAt ??
358	    (
359	      await getDb()<{ sync_started_at: string }>`
360	        SELECT clock_timestamp()::text AS sync_started_at
361	      `
362	    )[0].sync_started_at;
363	
364	  const creatorUserId = await resolveOrgCreator(organizationId);
365	  if (!creatorUserId) {
366	    logger.warn(
367	      { organization_id: organizationId, connector: connectorKey },
368	      'Access graph skipped: org has no member to attribute as entity creator',
369	    );
370	    return EMPTY_RESULT;
371	  }
372	
373	  await ensureResourceEntityType(organizationId);
374	  await ensurePersonEntityType(organizationId);
375	
376	  // ACL state uses a runtime connection id, while identity provenance references
377	  // the stored numeric row. Resolve by slug (chat connections) or id text (data
378	  // connectors) without assuming the runtime id itself is numeric.
379	  const [storedConnection] = await getDb()<{ id: number }>`
380	    SELECT id
381	    FROM connections
382	    WHERE organization_id = ${organizationId}
383	      AND connector_key = ${connectorKey}
384	      AND deleted_at IS NULL
385	      AND (
386	        slug = ${runtimeConnectionIdToSlug(connectionId)}
387	        OR id::text = ${connectionId}
388	      )
389	    LIMIT 1
390	  `;
391	  const identityConnectionId = storedConnection
392	    ? Number(storedConnection.id)
393	    : null;
394	
395	  // 1) Resolve every resource to its entity, keyed on the source identity namespace.
396	  const resourceItems = resources.map((r) => ({
397	    origin_type: 'access_resource',
398	    metadata: { resource_key: r.key, resource_name: r.name ?? r.key },
399	  }));
400	  const resolvedResources = await resolveEventAttributionsForItems({
401	    connectorKey,
402	    connectionId: identityConnectionId,
403	    orgId: organizationId,
404	    items: resourceItems,
405	    rules: {
406	      access_resource: [
407	        {
408	          role: 'belongs_to',
409	          entityType: ACL_RESOURCE_TYPE_SLUG,
410	          autoCreate: true,
411	          titlePath: 'metadata.resource_name',
412	          identities: [
413	            {
414	              namespace: resourceNamespace,
415	              eventPath: 'metadata.resource_key',
416	              primary: true,
417	            },
418	          ],
419	        },
420	      ],
421	    },
422	  });
423	  const resourceEntityIds: Record<string, number> = {};
424	  const resourceEntityIdByIndex = new Map<number, number>();
425	  for (let i = 0; i < resources.length; i++) {
426	    const ids = resolvedResources.get(i);
427	    if (ids && ids.length > 0) {
428	      resourceEntityIds[resources[i].key] = ids[0];
429	      resourceEntityIdByIndex.set(i, ids[0]);
430	    }
431	  }
432	
433	  // 2) Resolve every DISTINCT member (identity-first, type-agnostic).
434	  const distinctMembers = new Map<string, AccessMember>();
435	  for (const r of resources) {
436	    for (const m of r.members) {
437	      if (m.key && !distinctMembers.has(m.key)) distinctMembers.set(m.key, m);
438	    }
439	  }
440	  const memberEntityByKey = await resolveMembers(
441	    organizationId,
442	    connectorKey,
443	    identityConnectionId,
444	    [...distinctMembers.values()],
445	    memberIdentities,
446	  );
447	
448	  // 3) Write member → resource `member_of` edges, idempotent on the live-triple
449	  // unique index. Accumulate the CURRENT member set per resource for reconcile.
450	  const typeId = await ensureMemberOfType(organizationId);
451	  const sql = getDb();
452	
453	  // Keep each resource entity's display name fresh. `titlePath` only sets the
454	  // name on auto-CREATE, so a name that wasn't available at first graph (or a
455	  // later channel/repo RENAME) would otherwise stick to the stale value / the
456	  // raw id. Refresh from the source-provided name here. Scoped to the resources
457	  // in this build; idempotent (the locked selector skips unchanged names).
458	  const resourceNames = new Map<number, string>();
459	  for (let i = 0; i < resources.length; i++) {
460	    const id = resourceEntityIdByIndex.get(i);
  1	/**
  2	 * Platform → sender-identity mapping for chat-transcript attribution.
  3	 *
  4	 * The connector-agnostic core resolver (`resolveSenderIdentity` in
  5	 * entity-link-upsert) names no platform: it takes an already-normalized
  6	 * identity spec + the entity type to mint on a miss. THIS module is the
  7	 * connector-facing edge that turns a raw inbound chat author (platform, team,
  8	 * author id, bot flag) into that spec — the ONE place a platform's identity
  9	 * shape is known on the transcript path.
 10	 *
 11	 * A platform with no entry here (or a bot / malformed author) yields `null`:
 12	 * the message is still captured, just without `author_entity_id`.
 13	 */
 14	import { normalizeSlackUserId, SLACK_IDENTITY } from '@lobu/connectors/slack-identity';
 15	import type { ResolvedIdentity } from '../../utils/entity-link-upsert.js';
 16	
 17	export interface SenderIdentitySpec {
 18	  /** Normalized identity keys the sender is looked up / minted under. */
 19	  identities: ResolvedIdentity[];
 20	  /** Entity type to mint when no existing entity owns the identity. */
 21	  mintEntityType: string;
 22	}
 23	
 24	export interface RawChatSender {
 25	  platform: string;
 26	  teamId?: string | null;
 27	  authorId?: string | null;
 28	  isBot: boolean;
 29	}
 30	
 31	/**
 32	 * Build the normalized identity spec for a chat sender, or `null` when it
 33	 * shouldn't be attributed (a bot, an unknown platform, or a malformed id that
 34	 * would poison cross-workspace matching).
 35	 */
 36	export function buildSenderIdentity(sender: RawChatSender): SenderIdentitySpec | null {
 37	  // A bot post never attributes to a human entity.
 38	  if (sender.isBot) return null;
 39	
 40	  switch (sender.platform) {
 41	    case 'slack': {
 42	      // Team-scoped `T…:U…`; a bare `U…` with no team is dropped so a malformed,
 43	      // non-workspace-scoped key never poisons cross-workspace matching.
 44	      const slackId = normalizeSlackUserId(sender.teamId, sender.authorId);
 45	      if (!slackId) return null;
 46	      return {
 47	        identities: [
 48	          {
 49	            namespace: SLACK_IDENTITY.USER_ID,
 50	            identifier: slackId,
 51	            matchOnly: false,
 52	            primary: false,
 53	          },
 54	        ],
 55	        mintEntityType: 'person',
 56	      };
 57	    }
 58	    default:
 59	      return null;
 60	  }
 61	}

