135	 * Exported because the stamp is CONNECTION-wide while a build is per-resource-
136	 * set: a caller that reconciles one connection across several source scopes
137	 * (Slack Grid — one connection, many workspaces) must pass `markFresh: false`
138	 * and call this once, after every scope has been reconciled. Stamping inside
139	 * such a loop reopens the connection-wide gate while later scopes still hold
140	 * pre-revocation edges.
141	 */
142	export async function markAclFresh(
143	  orgId: string,
144	  connectionId: string,
145	  syncStartedAt: string,
146	): Promise<void> {
147	  const sql = getDb();
148	  await sql.begin(async (tx) => {
149	    // Serialize the state stamp with the connection tombstone. A sync can spend
150	    // seconds fetching a remote membership snapshot after the scheduler selected
151	    // the row; without this lock, deletion can remove the old ACL state and the
152	    // in-flight sync can recreate it after the delete commits. Standalone graph
153	    // tests intentionally use synthetic connection ids, so no matching row keeps
154	    // the historical materializer semantics; a matching tombstoned row skips the
155	    // stamp.
156	    const connections = await tx<{ deleted_at: Date | string | null }>`
157	      SELECT c.deleted_at
158	      FROM connections c
159	      WHERE c.organization_id = ${orgId}
160	        AND ${tx.unsafe(aclConnectionIdSql('c'))} = ${connectionId}
161	      FOR UPDATE
162	    `;
163	    if (connections.length > 0 && connections.every((row) => row.deleted_at != null)) return;
164	
165	    await tx`
166			INSERT INTO authz_source_acl_state
167				(organization_id, connection_id, acl_support, freshness_state, last_synced_at, created_at, updated_at)
168			VALUES (${orgId}, ${connectionId}, 'full', 'fresh', current_timestamp, current_timestamp, current_timestamp)
169			ON CONFLICT (organization_id, connection_id)
170			DO UPDATE SET acl_support = 'full', freshness_state = 'fresh',
171			              last_synced_at = clock_timestamp(), updated_at = clock_timestamp()
172			WHERE authz_source_acl_state.updated_at < ${syncStartedAt}::timestamptz
173		`;
174	  });
175	}
176	
177	/**
178	 * Resolve every distinct member to an entity id, IDENTITY-FIRST and
179	 * TYPE-AGNOSTIC: a member collapses onto any existing entity (`$member`,
180	 * `person`, …) carrying ANY of their identities; only genuinely-new members get
181	 * a freshly-created `person`. Returns a map member.key → entity id.
182	 */
183	async function resolveMembers(
184	  orgId: string,
185	  connectorKey: string,
186	  connectionId: number | null,
187	  members: AccessMember[],
188	  memberIdentities: AccessIdentitySpec[],
189	): Promise<Map<string, number>> {
190	  const byKey = new Map<string, number>();
191	  if (members.length === 0) return byKey;
192	
193	  // Gather identity values per namespace and look up existing owners (any type).
194	  const valuesByNamespace = new Map<string, Set<string>>();
195	  for (const m of members) {
196	    for (const id of m.identities) {
197	      if (!id.value) continue;
198	      const set = valuesByNamespace.get(id.namespace) ?? new Set<string>();
199	      set.add(id.value);
200	      valuesByNamespace.set(id.namespace, set);
201	    }
202	  }
203	  const existing = new Map<string, number>(); // `${namespace}|${value}` → entity id
204	  const sql = getDb();
205	  for (const [namespace, values] of valuesByNamespace) {
206	    const list = [...values];
207	    if (list.length === 0) continue;
208	    // The JOIN is load-bearing: an ordinary entity delete soft-deletes the
209	    // ENTITY but leaves its `entity_identities` rows live, still pointing at
210	    // it (only a merge or sign-in adoption repoints them). Matching on the
211	    // identity alone therefore resolves onto a dead entity, writes `member_of`
212	    // to it, and never mints a replacement — so the member silently vanishes
213	    // from the audience of every channel they are in. `lookupMatches` in
214	    // entity-link-upsert already joins for this reason; this matcher did not.
215	    const rows = await sql<{ identifier: string; entity_id: number }>`
216				SELECT ei.identifier, ei.entity_id
217				FROM entity_identities ei
218				JOIN entities e ON e.id = ei.entity_id
219				WHERE ei.organization_id = ${orgId}
220				  AND ei.namespace = ${namespace}
221				  AND ei.identifier = ANY(${pgTextArray(list)}::text[])
222				  AND ei.deleted_at IS NULL
223				  AND e.deleted_at IS NULL
224			`;
225	    for (const r of rows) {
226	      existing.set(`${namespace}|${String(r.identifier)}`, Number(r.entity_id));
227	    }
228	  }
229	
230	  // Which entity a member's claims resolve to follows the tier semantics the
231	  // create path below (`resolveEventAttributionsForItems`) already implements —
232	  // see `primary` in connector-types.ts. Stopping at the first array hit made
233	  // the answer depend on the order a connector pushed its identities, and
234	  // `member_of` is a read ACL, so that was a mis-grant waiting to happen: a
235	  // stale or recycled secondary claim (an old email, a reused login) would hand
 35	  teamId: string | null | undefined,
 36	  userId: string | null | undefined,
 37	): string | null {
 38	  if (typeof teamId !== 'string' || typeof userId !== 'string') return null;
 39	  const t = teamId.trim();
 40	  const u = userId.trim();
 41	  if (!t || !u) return null;
 42	  if (!/^[a-z0-9_-]+$/i.test(t) || !/^[a-z0-9_-]+$/i.test(u)) return null;
 43	  return `${t}:${u}`.toUpperCase();
 44	}
 45	
 46	/**
 47	 * Canonicalize an already-combined team-scoped Slack id (`T0XYZ:U12345`).
 48	 * Connectors/auth emit the team-prefixed form (build it with
 49	 * `normalizeSlackUserId(teamId, userId)`); this is the single-value cleanup
 50	 * pass the ingestion pipeline re-runs. Splits on the first colon and re-runs
 51	 * the two-part validator so a malformed value (no team prefix, bad chars)
 52	 * returns null rather than poisoning matching. Shared by user and channel ids
 53	 * (both are `TEAM:ID` shaped).
 54	 */
 55	function normalizeTeamScopedId(raw: string | null | undefined): string | null {
 56	  if (typeof raw !== 'string') return null;
 57	  const trimmed = raw.trim();
 58	  if (!trimmed) return null;
 59	  const sep = trimmed.indexOf(':');
 60	  if (sep <= 0 || sep === trimmed.length - 1) return null;
 61	  return normalizeSlackUserId(trimmed.slice(0, sep), trimmed.slice(sep + 1));
 62	}
 63	
 64	/**
 65	 * Normalize a Slack identity namespace value. Returns `undefined` when the
 66	 * namespace is not Slack-owned (caller should fall back to generic hygiene).
 67	 */
 68	export function normalizeSlackIdentityValue(
 69	  namespace: string,
 70	  raw: string,
 71	): string | null | undefined {
 72	  switch (namespace) {
 73	    case SLACK_IDENTITY.USER_ID:
 74	    case SLACK_IDENTITY.CHANNEL_ID:
 75	      return normalizeTeamScopedId(raw);
 76	    default:
 77	      return undefined;
 78	  }
 79	}
 80	
 81	/** The Slack connector's contribution to the server identity wiring. */
 82	export const slackIdentityModule: ConnectorIdentityModule = {
 83	  key: 'slack',
 84	  // slack_user_id is recall-indexed (idx_events_metadata_slack_user_id);
 85	  // slack_channel_id is an ACL resource key, not an event-recall namespace.
 86	  recallNamespaces: [SLACK_IDENTITY.USER_ID],
 87	  normalize: normalizeSlackIdentityValue,
 88	};
 89	
 90	// ── ACL source ────────────────────────────────────────────────────────────
 91	//
 92	// Slack channel membership is a read ACL: a requester may recall a channel iff
 93	// they are `member_of` it. The connector owns how a workspace's channels +
 94	// members normalize into the generic engine's resource/audience shape; the
 95	// server-side materializer (buildAccessGraph) does the IO.

