   131	const AGGS = new Set(['sum', 'count', 'min', 'max', 'count_distinct']);
   132	
   133	/**
   134	 * Validate a declared {@link EntityMetrics} contract. Returns a list of human
   135	 * error messages (empty ⇒ valid). Defensive about shape so it can validate
   136	 * untyped JSON at the server boundary as well as typed config at apply time.
   137	 *
   138	 * Catches what TypeScript can't: name references (a measure naming a missing
   139	 * eventSet/segment still typechecks — they're strings) and the
   140	 * `expr`-required-except-`count` rule. Pure; no Typebox-schema duplication of
   141	 * the structural guarantees authoring already gets from the types.
   142	 */
   143	export function validateEntityMetrics(metrics: unknown): string[] {
   144	  const errors: string[] = [];
   145	  if (metrics == null) return errors;
   146	  if (typeof metrics !== 'object' || Array.isArray(metrics)) {
   147	    return ['metrics must be an object'];
   148	  }
   149	  const m = metrics as Record<string, unknown>;
   150	  const asRecord = (v: unknown): Record<string, unknown> =>
   151	    v && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : {};
   152	
   153	  const eventSets = asRecord(m.eventSets);
   154	  const segments = asRecord(m.segments);
   155	  const measures = asRecord(m.measures);
   156	  const dimensions = asRecord(m.dimensions);
   157	  const eventSetNames = new Set(Object.keys(eventSets));
   158	  const segmentNames = new Set(Object.keys(segments));
   159	
   160	  for (const [name, raw] of Object.entries(measures)) {
   161	    const meas = asRecord(raw);
   162	    const agg = meas.agg;
   163	    if (typeof agg !== 'string' || !AGGS.has(agg)) {
   164	      errors.push(`measure "${name}": invalid agg "${String(agg)}"`);
   165	    }
   166	    if (agg !== 'count' && (typeof meas.expr !== 'string' || meas.expr.trim() === '')) {
   167	      errors.push(`measure "${name}": expr is required for agg "${String(agg)}"`);
   168	    }
   169	    if (typeof meas.eventSet !== 'string' || !eventSetNames.has(meas.eventSet)) {
   170	      errors.push(
   171	        `measure "${name}": eventSet "${String(meas.eventSet)}" is not a declared eventSet`,
   172	      );
   173	    }
   174	    if (typeof meas.description !== 'string' || meas.description.trim() === '') {
   175	      errors.push(`measure "${name}": description is required`);
   176	    }
   177	    const segs = meas.segments;
   178	    if (segs !== undefined) {
   179	      if (!Array.isArray(segs)) {
   180	        errors.push(`measure "${name}": segments must be an array`);
   181	      } else {
   182	        for (const s of segs) {
   183	          if (typeof s !== 'string' || !segmentNames.has(s)) {
   184	            errors.push(`measure "${name}": segment "${String(s)}" is not a declared segment`);
   185	          }
   186	        }
   187	      }
   188	    }
   189	  }
   190	
   191	  for (const [name, raw] of Object.entries(dimensions)) {
   192	    const dim = asRecord(raw);
   193	    if (typeof dim.expr !== 'string' || dim.expr.trim() === '') {
   194	      errors.push(`dimension "${name}": expr is required`);
   195	    }
   196	    if (typeof dim.description !== 'string' || dim.description.trim() === '') {
   197	      errors.push(`dimension "${name}": description is required`);
   198	    }
   199	  }
   200	
   201	  return errors;
   202	}
